import express from "express";
import { randomUUID } from "node:crypto";

export const app = express();
app.use(express.json());

const produk = [
  { id: 1, nama: "Kopi Susu Gula Aren", harga: 18000 },
  { id: 2, nama: "Roti Bakar Cokelat", harga: 15000 },
  { id: 3, nama: "Teh Melati", harga: 8000 },
];

// Gangguan buatan untuk latihan alert. Hanya bisa diubah kalau FAULT_ENABLED=1.
const fault = { errorRate: 0, extraLatencyMs: 0 };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function kerja(baseMs) {
  await sleep(baseMs + Math.random() * baseMs + fault.extraLatencyMs);
  if (Math.random() < fault.errorRate) {
    throw new Error("gangguan simulasi: database tidak menjawab");
  }
}

app.get("/healthz", (req, res) => res.json({ status: "ok" }));

app.get("/api/produk", async (req, res) => {
  await kerja(20);
  res.json(produk);
});

app.get("/api/produk/:id", async (req, res) => {
  await kerja(15);
  const item = produk.find((p) => p.id === Number(req.params.id));
  if (!item) return res.status(404).json({ error: "Produk tidak ditemukan" });
  res.json(item);
});

app.post("/api/checkout", async (req, res) => {
  await kerja(80);
  res.status(201).json({ pesanan: randomUUID() });
});

if (process.env.FAULT_ENABLED === "1") {
  app.post("/admin/fault", (req, res) => {
    const { errorRate = 0, extraLatencyMs = 0 } = req.body ?? {};
    if (!(errorRate >= 0 && errorRate <= 1) || !(extraLatencyMs >= 0 && extraLatencyMs <= 5000)) {
      return res.status(422).json({ error: "errorRate 0..1, extraLatencyMs 0..5000" });
    }
    Object.assign(fault, { errorRate, extraLatencyMs });
    console.log("gangguan simulasi diubah", fault);
    res.json(fault);
  });
}

app.use((req, res) => res.status(404).json({ error: "Tidak ditemukan" }));

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: "Terjadi kesalahan di server" });
});

