import client from "prom-client";

export const register = new client.Registry();
client.collectDefaultMetrics({ register });

const requests = new client.Counter({
  name: "http_requests_total",
  help: "Jumlah request HTTP yang selesai",
  labelNames: ["method", "route", "status"],
  registers: [register],
});

const duration = new client.Histogram({
  name: "http_request_duration_seconds",
  help: "Durasi request HTTP dalam detik",
  labelNames: ["method", "route"],
  // 0.3 wajib ada: batas SLO latensi kita 300 ms
  buckets: [0.05, 0.1, 0.2, 0.3, 0.5, 1, 2, 5],
  registers: [register],
});

export function record({ method, route, status, seconds }) {
  requests.inc({ method, route, status: String(status) });
  duration.observe({ method, route }, seconds);
}

