import express from "express";
import { randomUUID } from "node:crypto";
import { logger } from "./logger.js";
import { record, register } from "./metrics.js";

export const app = express();
app.use(express.json());

// Satu middleware untuk metrik RED dan log akses.
app.use((req, res, next) => {
  const start = process.hrtime.bigint();
  req.id = req.get("x-request-id") ?? randomUUID();
  res.set("x-request-id", req.id);
  res.on("finish", () => {
    // Pakai pola rute (/api/produk/:id), bukan URL asli, supaya label tidak meledak.
    const route = req.route ? req.baseUrl + req.route.path : "tidak-dikenal";
    if (route === "/metrics") return;
    const seconds = Number(process.hrtime.bigint() - start) / 1e9;
    record({ method: req.method, route, status: res.statusCode, seconds });
    const level = res.statusCode >= 500 ? "error" : "info";
    logger[level]({
      req_id: req.id,
      method: req.method,
      route,
      path: req.originalUrl,
      status: res.statusCode,
      duration_ms: Math.round(seconds * 1000),
    }, "request selesai");
  });
  next();
});

