// Cari kontainer lewat Docker API, hanya yang servis compose-nya "layanan".
discovery.docker "kontainer" {
  host = "unix:///var/run/docker.sock"

  filter {
    name   = "label"
    values = ["com.docker.compose.service=layanan"]
  }
}

// Ubah label metadata Docker menjadi label log yang rapi.
discovery.relabel "log" {
  targets = []

  rule {
    source_labels = ["__meta_docker_container_label_com_docker_compose_service"]
    target_label  = "service"
  }
}

loki.source.docker "layanan" {
  host          = "unix:///var/run/docker.sock"
  targets       = discovery.docker.kontainer.targets
  relabel_rules = discovery.relabel.log.rules
  forward_to    = [loki.process.json.receiver]
}

// Ambil field "level" dari log JSON pino dan jadikan label (nilainya sedikit: info/warn/error).
loki.process "json" {
  stage.json {
    expressions = { level = "level" }
  }

  stage.labels {
    values = { level = "" }
  }

  forward_to = [loki.write.lokal.receiver]
}

loki.write "lokal" {
  endpoint {
    url = "http://loki:3100/loki/api/v1/push"
  }
}

