// Penerima webhook Alertmanager: cukup mencetak alert ke log.
import http from "node:http";

http.createServer((req, res) => {
  let body = "";
  req.on("data", (c) => (body += c));
  req.on("end", () => {
    try {
      const { alerts = [] } = JSON.parse(body);
      for (const a of alerts) {
        console.log(`[${a.status.toUpperCase()}] ${a.labels.alertname} severity=${a.labels.severity} - ${a.annotations.summary ?? ""}`);
      }
    } catch {
      console.log("payload bukan JSON:", body.slice(0, 200));
    }
    res.end("ok");
  });
}).listen(8080, () => console.log("penerima alert siap di :8080"));

// Pemakaian: node skrip/beban.mjs [detik=300] [request_per_detik=20]
const BASE = process.env.BASE_URL ?? "http://localhost:3000";
const detik = Number(process.argv[2] ?? 300);
const rps = Number(process.argv[3] ?? 20);
const jalur = [
  ["GET", "/api/produk"],
  ["GET", "/api/produk/1"],
  ["GET", "/api/produk/99"], // 404 sengaja: bukan error server
  ["POST", "/api/checkout"],
];
const hitung = {};
const tambah = (k) => (hitung[k] = (hitung[k] ?? 0) + 1);
const akhir = Date.now() + detik * 1000;

while (Date.now() < akhir) {
  for (let i = 0; i < rps; i++) {
    const [method, path] = jalur[Math.floor(Math.random() * jalur.length)];
    fetch(BASE + path, { method }).then((r) => tambah(r.status), () => tambah("gagal"));
  }
  await new Promise((r) => setTimeout(r, 1000));
  console.log(new Date().toISOString().slice(11, 19), JSON.stringify(hitung));
}
